  urges:['Alcool Info Service : comprendre et traverser une envie de boire','https://alcool-info-service.fr/agir-sur-sa-consommation/comment-arreter-de-boire/vous-avez-envie-de-boire-de-lalcool-comment'],
  nhs:['NHS : réduire sa consommation, bénéfices et précautions (en anglais)','https://www.nhs.uk/better-health/drink-less/'],
