const safety=`<aside class="callout safety"><p><strong>Préparer un arrêt en sécurité.</strong> Une consommation importante ou quotidienne, des signes de manque ou un sevrage déjà difficile justifient un avis médical avant un arrêt brutal ou une forte réduction. Confusion, hallucinations ou convulsions : appelle le 15 ou le 112. Sobrizen est un soutien, sans diagnostic ni protocole de sevrage.</p></aside>`;
const privacy='<p class="privacy-note">Le calcul reste dans cette page. Tes saisies ne sont pas envoyées à Sobrizen et ne sont pas sauvegardées automatiquement. Aucun compte n’est nécessaire.</p>';
const toolCounter=`<form class="tool" data-tool="counter" id="outil" novalidate><fieldset disabled data-controls><span class="eyebrow">Outil gratuit · Sans inscription</span><h2>Ton compteur de jours sans alcool</h2><p class="tool-intro">Choisis ta date de départ. Le calcul utilise les dates du calendrier, sans inventer une heure de dernier verre.</p><div class="form-grid"><div class="field"><label for="counter-start">Date de départ de cette période</label><input type="date" id="counter-start" name="start" min="1900-01-01" required><small>Le jour de départ correspond à zéro jour écoulé.</small></div></div><button class="button" type="submit">Calculer mes jours</button><p class="error" data-error role="alert"></p><div class="result-panel" data-result role="status" aria-live="polite" aria-atomic="true" hidden><strong class="big-number" data-count></strong><p class="result-caption" data-counter-caption></p><p class="result-caption" data-next-cap></p></div>${privacy}<noscript><p>Active JavaScript pour calculer ce compteur. L’explication et la méthode restent lisibles ci-dessous.</p></noscript></fieldset></form>`;
const toolBudget=`<form class="tool" data-tool="budget" id="outil" novalidate><fieldset disabled data-controls><span class="eyebrow">Outil gratuit · Sans inscription</span><h2>Calcule tes économies sur l’alcool</h2><p class="tool-intro">Compare ton budget habituel et ton nouveau budget hebdomadaire. Tu peux inclure le coût des boissons de remplacement dans le second montant.</p><div class="form-grid"><div class="field"><label for="budget-before">Budget habituel par semaine (€)</label><input id="budget-before" name="before" type="text" inputmode="decimal" value="35" maxlength="8" required><small>Exemple : achats à la maison et consommations à l’extérieur.</small></div><div class="field"><label for="budget-after">Nouveau budget par semaine (€)</label><input id="budget-after" name="after" type="text" inputmode="decimal" value="0" maxlength="8" required><small>Alcool éventuel et boissons de remplacement, selon ce que tu compares.</small></div></div><button class="button" type="submit">Calculer la différence</button><p class="error" data-error role="alert"></p><div class="result-panel" data-result role="status" aria-live="polite" aria-atomic="true" hidden><div class="money-results"><div><strong data-money="weekly"></strong><span>sur 7 jours</span></div><div><strong data-money="month"></strong><span>sur 30 jours</span></div><div><strong data-money="year"></strong><span>sur 365 jours</span></div></div><p class="result-caption" data-budget-caption></p></div>${privacy}<noscript><p>Active JavaScript pour utiliser le calculateur. La formule et un exemple sont disponibles ci-dessous.</p></noscript></fieldset></form>`;
const toolCalendar=`<section class="tool" data-tool="calendar" id="outil"><span class="eyebrow">Outil gratuit · Sans inscription</span><h2>Ton calendrier sans alcool à imprimer</h2><p class="tool-intro">Choisis ton mois, puis clique sur une journée passée ou sur aujourd’hui : non renseigné → sans alcool → avec alcool → non renseigné. Une case vide n’est jamais comptée comme un jour sans alcool.</p><div class="calendar-toolbar"><div class="field"><label for="calendar-month">Mois du calendrier</label><input id="calendar-month" name="month" type="month" min="1900-01" max="2100-12"></div><button type="button" class="button" data-print>Imprimer / enregistrer en PDF</button></div><p class="error" data-error role="alert"></p><p class="calendar-legend">S : sans alcool · A : avec alcool · — : non renseigné</p><div class="calendar-sheet"><p class="print-only"><strong>SobriZen · Mon calendrier d’observation</strong><br>www.sobrizen.com/blog/calendrier-sans-alcool-a-imprimer</p><h3 data-calendar-title></h3><div class="calendar-weekdays" aria-hidden="true"><span>Lun.</span><span>Mar.</span><span>Mer.</span><span>Jeu.</span><span>Ven.</span><span>Sam.</span><span>Dim.</span></div><div class="calendar-grid" data-calendar-grid aria-label="Observations du mois"></div><p class="calendar-total" role="status" aria-live="polite" aria-atomic="true"><strong data-observed>0</strong> jours renseignés · <strong data-without>0</strong> sans alcool · <strong data-with>0</strong> avec alcool</p><p class="print-only print-notes">Mes observations / mon prochain petit pas :<br>___________________________________________________________________<br>___________________________________________________________________</p></div><p class="tool-help">Les dates futures restent vierges pour l’impression. Tes choix sont conservés seulement pendant que cette page reste ouverte ; imprime ou enregistre ton calendrier avant de la fermer.</p><div class="button-row no-print"><a class="button secondary" href="/blog/calendrier-sans-alcool-vierge.pdf" download>Télécharger le PDF vierge</a></div>${privacy}<noscript><p>Le calendrier interactif demande JavaScript. Tu peux toujours <a href="/blog/calendrier-sans-alcool-vierge.pdf">télécharger le calendrier vierge en PDF</a>.</p></noscript></section>`;
const eveningPlan=`<form class="tool" data-evening-plan id="mon-plan" novalidate><fieldset disabled data-controls><h2>Prépare ton prochain soir</h2><p class="tool-intro">Trois éléments simples pour transformer une intention en organisation concrète. Cet exercice ne traite pas un manque physique.</p><div class="field"><label for="plan-moment">Le moment à anticiper</label><input id="plan-moment" name="moment" maxlength="180" placeholder="je rentre du travail" autocomplete="off"></div><div class="form-grid"><div class="field"><label for="plan-alternative">Mon alternative réaliste</label><input id="plan-alternative" name="alternative" maxlength="180" placeholder="une eau pétillante et dix minutes dehors" autocomplete="off"></div><div class="field"><label for="plan-support">Mon appui si besoin</label><input id="plan-support" name="support" maxlength="180" placeholder="appeler une personne de confiance" autocomplete="off"></div></div><button class="button" type="submit">Formuler mon plan</button><p class="error" data-error role="alert"></p><div class="result-panel" data-result role="status" aria-live="polite" hidden><p data-plan-text></p></div>${privacy}<noscript><p>Active JavaScript pour formuler le plan, ou recopie les trois questions dans un carnet privé.</p></noscript></fieldset></form>`;

const articles=[
{
slug:'calendrier-sans-alcool-a-imprimer',title:'Calendrier sans alcool à imprimer : ton suivi mensuel',category:'Observer ses habitudes',minutes:5,tool:toolCalendar,
description:'Crée ton calendrier sans alcool gratuit : jours avec ou sans consommation, mois au choix, impression et PDF vierge. Aucun compte nécessaire.',
intro:'Un calendrier sans alcool à imprimer peut rendre tes habitudes plus visibles. Choisis un mois, renseigne seulement ce que tu sais et garde une trace sur papier ou en PDF. Tu peux aussi commencer par le calendrier vierge, sans remplir quoi que ce soit en ligne.',
sections:[
['mode-emploi','Comment remplir ton calendrier de consommation d’alcool',`<p>Commence par une question simple : as-tu consommé de l’alcool pendant cette journée ? Choisis « sans alcool » ou « avec alcool ». Si tu ne sais plus, laisse la case « non renseigné ». Le calendrier sert à observer ; il ne demande pas de reconstruire un passé incertain.</p><p>Tu peux renseigner une journée à la fois, à un moment qui te convient. Ameli propose de noter ses consommations sur plusieurs semaines pour mieux comprendre ses habitudes. Ici, le calendrier est volontairement simplifié : il indique les jours, sans calculer les quantités ni un risque médical.</p><ol><li><strong>Choisis le mois.</strong> Tu peux revenir sur une période passée ou imprimer un mois à venir.</li><li><strong>Renseigne les journées connues.</strong> Clique à nouveau pour corriger une case. Aucune journée n’est remplie à ta place.</li><li><strong>Regarde les totaux.</strong> Ils distinguent jours renseignés, jours sans alcool et jours avec alcool.</li><li><strong>Garde ton document.</strong> Utilise « Imprimer / enregistrer en PDF » ou le PDF vierge pour une version papier.</li></ol>`],
['lire-calendrier','Ce que ton calendrier montre, et ce qu’il ne montre pas',`<p>Une série de cases aide à repérer des répétitions : une consommation surtout le week-end, un jour de la semaine plus difficile ou une période différente des autres. Ce sont des pistes à explorer, pas des conclusions sur ta personnalité.</p><p>Un jour avec alcool ne dit rien, à lui seul, sur la quantité consommée. Un total de jours sans alcool ne suffit pas non plus à évaluer le niveau de risque. Si tu souhaites préparer un échange avec un professionnel, note séparément les boissons, les quantités, les circonstances et les questions que tu veux poser.</p><div class="callout"><p><strong>Exemple fictif :</strong> sur dix jours renseignés, six sont marqués sans alcool et quatre avec alcool. Les autres cases du mois restent inconnues. On ne peut donc pas dire que le mois comporte vingt-six jours sans alcool.</p></div>`],
['utiliser-papier','Utiliser le PDF sans transformer le suivi en obligation',`<p>Le PDF vierge comporte trente et une cases numérotées. Écris le mois et l’année, puis barre les jours qui n’existent pas dans ce mois. Utilise des lettres ou des signes si tu imprimes en noir et blanc : « S » pour sans alcool, « A » pour avec alcool et rien quand l’information manque.</p><p>Tu peux garder le calendrier à un endroit privé, ou l’apporter à une consultation si tu le souhaites. Le remplir n’a pas à devenir un examen quotidien. Une reprise de consommation peut être notée comme n’importe quelle observation, sans effacer les journées précédentes.</p><p>Si tu préfères un historique modifiable et plus détaillé, Sobrizen permet de suivre des jours et des périodes dans un espace personnel. Le ${link('compteur-jours-sans-alcool','compteur de jours sans alcool')} répond à une autre question : combien de jours se sont écoulés depuis une date de départ ?</p>`],
['bilan','Trois questions pour faire ton bilan du mois',`<ul><li>Quelles situations reviennent dans les journées avec consommation ?</li><li>Qu’est-ce qui m’a aidé lors des journées où j’ai suivi mon intention ?</li><li>Quel ajustement réaliste ou quel soutien serait utile pour la suite ?</li></ul><p>Tu peux compléter ce bilan par une ${link('calcul-economies-arret-alcool','estimation des économies sur l’alcool')} ou préparer un ${link('ne-plus-boire-alcool-le-soir','rituel du soir différent')}. Les outils organisent tes observations ; ils ne décident pas à ta place d’un objectif de consommation.</p>`]
],
faq:[['Le calendrier sans alcool est-il gratuit ?','Oui. Le calendrier interactif, son impression et le PDF vierge sont accessibles sans inscription ni abonnement.'],['Mes observations sont-elles enregistrées ?','Non. Les choix restent dans la mémoire de cette page pendant son ouverture. Un rechargement les efface. Imprime ou enregistre le PDF pour garder une trace.'],['Puis-je suivre une réduction plutôt qu’un arrêt ?','Oui. Tu peux observer les jours avec et sans alcool. Pour suivre les quantités, complète le document avec tes propres notes ou utilise un suivi plus détaillé.']],
sources:['habits','reduce','withdrawal']
},
{
slug:'calcul-economies-arret-alcool',title:'Économies en arrêtant l’alcool : le calculateur',category:'Budget & motivation',minutes:5,tool:toolBudget,
description:'Calcule l’argent économisé en réduisant ou en arrêtant l’alcool sur 7, 30 et 365 jours. Budget personnalisable, formule expliquée, sans inscription.',
intro:'Combien d’argent peux-tu économiser en réduisant ou en arrêtant l’alcool ? Le montant dépend de tes dépenses réelles, de tes nouvelles habitudes et de ce qui remplace les boissons habituelles. Ce calculateur compare deux budgets hebdomadaires, sans inventer une consommation moyenne.',
sections:[
['estimer-budget','Commencer par tes dépenses habituelles',`<p>Pour obtenir une estimation utile, pars d’une semaine qui ressemble à ton rythme habituel. Additionne les achats destinés à ta consommation à la maison et les boissons payées à l’extérieur. Si tes semaines varient beaucoup, observe plusieurs semaines et divise le total par leur nombre.</p><p>Il n’est pas nécessaire de chercher un prix au centime près lorsque tu n’as pas les tickets. Tu peux saisir une estimation, puis la corriger. En revanche, évite de compter deux fois le même achat : une bouteille achetée en magasin et les verres que tu en tires représentent une seule dépense.</p><p>Pour un budget partagé, choisis une règle cohérente. Tu peux suivre uniquement ta part ou le budget du foyer, à condition d’utiliser le même périmètre dans les deux champs. Le résultat sera d’autant plus lisible.</p>`],
['formule','La formule de calcul des économies sur l’alcool',`<p>Le calcul utilise la différence entre tes deux budgets :</p><div class="callout"><p><strong>Différence hebdomadaire = budget habituel − nouveau budget.</strong><br>Projection sur 30 jours = différence hebdomadaire × 30 ÷ 7.<br>Projection sur 365 jours = différence hebdomadaire × 365 ÷ 7.</p></div><p>Les horizons sont fixes : trente jours ne représentent pas tous les mois du calendrier, et trois cent soixante-cinq jours correspondent ici à une année de projection. Le calcul n’utilise ni intérêts financiers, ni inflation, ni augmentation supposée du prix des boissons.</p><p>Si le nouveau budget dépasse le précédent, le résultat est négatif. Cela indique un surcoût dans le périmètre choisi. Le calculateur l’affiche plutôt que de masquer cette différence.</p>`],
['exemples','Exemples : arrêt, réduction et boissons de remplacement',`<div class="table-wrap"><table><caption>Exemples fictifs, avec des budgets constants</caption><thead><tr><th>Situation</th><th>Par semaine</th><th>Sur 30 jours</th><th>Sur 365 jours</th></tr></thead><tbody><tr><td>35 € avant, 0 € après</td><td>35 €</td><td>150 €</td><td>1 825 €</td></tr><tr><td>35 € avant, 7 € après</td><td>28 €</td><td>120 €</td><td>1 460 €</td></tr><tr><td>21 € avant, 14 € après</td><td>7 €</td><td>30 €</td><td>365 €</td></tr></tbody></table></div><p>Le second champ peut inclure les boissons de remplacement si tu veux comparer l’ensemble de ton nouveau budget boissons. Une eau pétillante ou une boisson sans alcool achetée a aussi un coût ; l’intégrer évite de surestimer l’écart de dépenses.</p><p>Tu peux également choisir de comparer uniquement les dépenses d’alcool. Dans ce cas, lis le résultat comme un écart sur ce poste précis, et non comme l’évolution de toutes tes dépenses.</p>`],
['garder-motivation','Transformer le chiffre en repère personnel',`<p>Une projection n’est pas une somme déjà présente sur ton compte. Les dépenses évitées peuvent être absorbées par d’autres achats. Si tu veux garder une trace concrète, relève tes dépenses réelles au fil des semaines et compare-les à ton estimation de départ.</p><p>Tu peux donner à ce budget une destination qui te parle : une sortie, un projet ou simplement davantage de marge. L’objectif n’est pas de mesurer la valeur de ta démarche en euros. Une période moins régulière ne retire rien aux observations et aux choix déjà faits.</p><p>Associe le budget à ton ${link('calendrier-sans-alcool-a-imprimer','calendrier de consommation')} pour comprendre les variations. Dans l’application Sobrizen, les dépenses saisies et les estimations sont distinguées pour que tu puisses lire les montants avec leur contexte.</p>`]
],
faq:[['Le calculateur fonctionne-t-il si je réduis sans arrêter ?','Oui. Saisis ton budget habituel puis le budget correspondant à ta nouvelle consommation. Le calcul repose sur leur différence.'],['Pourquoi mon résultat diffère-t-il d’un calcul sur 52 semaines ?','Cinquante-deux semaines correspondent à 364 jours. Cet outil utilise explicitement 365 jours pour la projection annuelle et 30 jours pour la projection mensuelle.'],['Ces économies sont-elles garanties ?','Non. Ce sont des projections à budgets constants. Tes dépenses réelles peuvent évoluer ; tu peux revenir ajuster les deux montants.']],
sources:['nhs','habits','withdrawal']
},
{
slug:'compteur-jours-sans-alcool',title:'Compteur de jours sans alcool : ta progression',category:'Suivre sa progression',minutes:5,tool:toolCounter,
description:'Compte tes jours sans alcool depuis une date choisie avec ce compteur gratuit en ligne. Calcul transparent, sans compte, sans sauvegarde automatique.',
intro:'Un compteur de jours sans alcool donne un repère simple : le nombre de jours écoulés depuis une date que tu choisis. Il peut aider à visualiser une période, sans résumer tout ton parcours à un chiffre. Ici, le calcul est gratuit et reste dans cette page.',
sections:[
['calcul','Comment fonctionne ce compteur de sobriété ?',`<p>Saisis la date de départ de la période que tu souhaites regarder, puis lance le calcul. Le compteur compare cette date à la date du jour sur ton appareil. Il ne demande ni adresse email, ni inscription, ni historique de consommation.</p><p>Le jour de départ vaut zéro jour écoulé. Si tu choisis hier, le résultat vaut un jour. Ce mode de calcul est volontairement explicite : il compare des dates civiles, pas des heures exactes. Une date de départ seule ne permettrait pas d’affirmer que vingt-quatre heures complètes sont passées depuis le dernier verre.</p><div class="callout"><p><strong>Exemple :</strong> du 1er au 11 novembre, dix jours se sont écoulés entre les dates. Le compteur n’en déduit pas une heure de début, une quantité consommée auparavant ou un effet sur la santé.</p></div><p>Les changements d’heure ne rajoutent ni ne retirent une journée dans ce calcul de calendrier. Si l’appareil indique une mauvaise date, corrige d’abord son réglage pour obtenir un résultat cohérent.</p>`],
['date-depart','Quelle date de départ choisir ?',`<p>Tu peux choisir le début de ton arrêt en cours ou celui d’une période que tu veux observer. Si tu ne connais pas la date précise, il vaut mieux garder une estimation clairement identifiée dans tes notes que présenter le chiffre comme exact.</p><p>Le choix de compter à partir du dernier verre ou du premier jour entier sans alcool peut changer l’affichage d’une journée. Il n’existe pas ici de règle de concours : l’essentiel est de comprendre la convention utilisée et de garder le même repère dans ton suivi.</p><p>Pour noter des arrêts, des reprises et des jours sans consommation qui ne se suivent pas, un ${link('calendrier-sans-alcool-a-imprimer','calendrier avec des observations distinctes')} sera plus informatif qu’un compteur unique.</p>`],
['apres-reprise','Après une reprise, le parcours ne disparaît pas',`<p>Si tu recommences une nouvelle période sans alcool, tu peux modifier la date. Le résultat affiché change, mais les périodes précédentes ont bien existé. Ce petit outil ne conserve pas d’historique ; il ne peut donc pas afficher tes jours cumulés ni tes anciennes séries.</p><p>Avant de repartir d’un nouveau chiffre, tu peux noter ce qui s’est passé : le contexte, les besoins du moment et le soutien qui a manqué. Cette observation peut servir à préparer la suite, seul ou avec un professionnel selon ta situation.</p><p>Dans Sobrizen, le suivi par jours et périodes permet de garder une trace plus large. Un compteur public reste une porte d’entrée légère ; l’application sert à retrouver plusieurs observations dans la durée.</p>`],
['autres-reperes','Quels autres repères regarder à côté du nombre de jours ?',`<ul><li>Les situations dans lesquelles tu as pu suivre ton intention.</li><li>Les envies rencontrées et les appuis que tu as sollicités.</li><li>Ton ressenti sur le sommeil et l’énergie, sans attendre une évolution linéaire.</li><li>Les ${link('calcul-economies-arret-alcool','dépenses évitées estimées')} et les dépenses réellement notées.</li></ul><p>À dix ou quinze jours, tu peux utiliser notre ${link('10-15-jours-sans-alcool-bienfaits','guide pour faire le point sur cette étape')}. Le chiffre du compteur ne permet pas de savoir si le foie a récupéré ou si un symptôme est sans gravité. Pour ces questions, un avis médical apporte le contexte nécessaire.</p>`]
],
faq:[['Le compteur reste-t-il enregistré après fermeture ?','Non. Il ne stocke pas ta date. Note le résultat si tu veux le conserver ou utilise un suivi personnel avec historique.'],['Puis-je calculer depuis une date future ?','Non. Une date future ne représente pas une période déjà écoulée. Le formulaire demande une date passée ou aujourd’hui.'],['Le compteur remplace-t-il un suivi médical ?','Non. Il effectue seulement une différence entre deux dates. Il ne mesure ni dépendance, ni risque de sevrage, ni récupération physique.']],
sources:['habits','reduce','withdrawal']
},
{
slug:'10-15-jours-sans-alcool-bienfaits',title:'10 à 15 jours sans alcool : bienfaits et repères',category:'Comprendre les changements',minutes:6,
description:'10 ou 15 jours sans alcool : quels changements observer sur le sommeil, l’énergie et les envies ? Des repères prudents, des sources et un bilan simple.',
intro:'Après dix à quinze jours sans alcool, tu peux avoir envie de savoir ce qui devrait déjà avoir changé. Il n’existe pourtant pas de calendrier biologique identique pour tout le monde. Ce cap peut surtout devenir un moment pour observer tes ressentis, repérer les difficultés et ajuster ton accompagnement.',
sections:[
['changements','Quels bienfaits peut-on ressentir après 10 à 15 jours sans alcool ?',`<p>Réduire sa consommation peut s’accompagner d’un meilleur repos, de davantage d’énergie ou d’un budget différent. Les ressources du NHS décrivent ces bénéfices possibles, sans annoncer qu’ils apparaissent nécessairement au dixième ou au quinzième jour.</p><p>Le sommeil, l’humeur et l’énergie n’évoluent pas toujours ensemble. Tu peux remarquer un réveil plus facile tout en continuant à traverser des soirées compliquées. Tu peux aussi ne pas percevoir de changement clair. Cela ne suffit pas à conclure que la démarche serait inutile.</p><p>Les habitudes précédentes, la santé, les traitements, le stress et l’organisation de la vie jouent un rôle dans ce que tu observes. Un article général ne peut pas interpréter ces éléments pour une personne donnée.</p>`],
['sommeil','Sommeil et fatigue : observer plutôt qu’attendre un résultat à date fixe',`<p>L’alcool peut donner une impression d’endormissement plus facile tout en perturbant la qualité du sommeil. Boire moins peut aider à mieux se reposer, mais un arrêt peut aussi s’accompagner de troubles du sommeil. Des difficultés persistantes ou gênantes méritent un avis professionnel.</p><p>Pour faire le point, choisis une observation courte, par exemple : « sommeil peu réparateur, moyen ou réparateur ». Tu peux ajouter une phrase sur la soirée précédente, sans tenter d’attribuer chaque variation à l’alcool.</p><div class="callout"><p><strong>Un bilan plus utile qu’une comparaison :</strong> « Qu’ai-je remarqué cette semaine par rapport à la précédente ? » apporte souvent davantage de contexte que « Pourquoi n’ai-je pas les mêmes résultats que quelqu’un à J10 ? »</p></div>`],
['envies','Pourquoi une envie de boire peut-elle encore survenir ?',`<p>Les envies peuvent être liées à une heure, une émotion, un lieu ou une situation sociale associés à la consommation. Leur présence ne prouve pas un manque de volonté. Alcool Info Service propose de repérer ces déclencheurs et de préparer des alternatives ou un appui.</p><p>Tu peux noter l’heure de l’envie, son contexte et ce que tu as essayé. Une observation comme « retour du travail, besoin de couper, appel à un proche » décrit une situation concrète. Elle peut aider à préparer le lendemain ou un échange avec un professionnel.</p><p>Notre ${link('ne-plus-boire-alcool-le-soir','guide pour changer le rituel du soir')} propose un plan en trois éléments. Il ne faut pas confondre une organisation du quotidien avec la prise en charge de symptômes physiques de manque.</p>`],
['foie-poids','Foie, gamma-GT, poids : ce qu’on ne peut pas conclure à J10 ou J15',`<p>On ne peut pas affirmer, à partir du seul nombre de jours, que le foie est « nettoyé », qu’un bilan sanguin s’est normalisé ou qu’un certain nombre de kilos aurait dû être perdu. Un résultat d’analyse se lit avec un professionnel et avec le contexte de santé.</p><p>Une étude observationnelle publiée dans BMJ Open a constaté des améliorations de plusieurs paramètres après un mois d’abstinence chez des participants volontaires. Elle ne portait pas sur un résultat garanti à dix ou quinze jours et excluait notamment les personnes dépendantes ou ayant une maladie hépatique connue.</p><p>Pour lire les résultats avec leurs limites, retrouve notre ${link('bienfaits-arret-alcool-jour-apres-jour','article sur les bienfaits au fil des jours et des semaines')}. Évite les promesses de transformation rapide : elles peuvent créer des attentes que ton corps n’a aucune obligation de suivre.</p>`],
['bilan','Ton bilan en cinq observations',`<p>Prends quelques minutes et note ce qui est réellement connu :</p><ol><li><strong>Les jours observés :</strong> utilise le ${link('calendrier-sans-alcool-a-imprimer','calendrier mensuel')} en laissant les jours inconnus vierges.</li><li><strong>Le sommeil :</strong> un ressenti global et, si utile, un exemple de nuit.</li><li><strong>L’énergie :</strong> les moments faciles et les moments de fatigue.</li><li><strong>Les envies :</strong> les circonstances et les appuis disponibles.</li><li><strong>Le budget :</strong> les achats réellement évités ou une ${link('calcul-economies-arret-alcool','projection clairement identifiée')}.</li></ol><p>Ce bilan n’a pas besoin d’être positif sur tous les points. Il peut servir à décider d’un petit ajustement ou à préparer une consultation. Une gêne importante ne doit pas être minimisée parce qu’un objectif de dix ou quinze jours a été atteint.</p>`]
],
faq:[['Est-ce normal de ne pas ressentir un grand changement après quinze jours ?','Les expériences varient. L’absence de changement spectaculaire ne permet pas de juger l’ensemble de la démarche. Un symptôme persistant, nouveau ou gênant mérite un avis médical.'],['Le foie est-il rétabli après dix jours sans alcool ?','Le nombre de jours ne permet pas de l’affirmer. L’état du foie dépend de la situation initiale et doit, si nécessaire, être évalué médicalement.'],['Dois-je supporter seul des tremblements ou des malaises ?','Non. Ces signes peuvent nécessiter une évaluation médicale. Ne les traite pas comme une simple étape à traverser avec un compteur ou une application.']],
sources:['sleep','nhs','urges','withdrawal','study']
},
{
slug:'bienfaits-arret-alcool-jour-apres-jour',title:'Arrêt de l’alcool : les bienfaits jour après jour',category:'Comprendre les changements',minutes:7,
description:'Les bienfaits possibles de l’arrêt de l’alcool au fil des jours et semaines : sommeil, énergie, budget et santé. Chronologie prudente et sources fiables.',
intro:'Chercher les bienfaits de l’arrêt de l’alcool jour après jour est une façon compréhensible de vouloir se projeter. Une chronologie peut aider à organiser ses observations, mais elle ne doit pas annoncer une transformation obligatoire à chaque date. Voici des repères pour lire les changements avec leur contexte.',
sections:[
['premiers-jours','Les premiers jours : sécuriser la démarche',`<p>Avant de chercher une liste de bénéfices, il faut tenir compte des conditions de l’arrêt. En cas de consommation importante ou quotidienne, de symptômes de manque ou d’antécédent de sevrage difficile, un avis médical est nécessaire avant un arrêt brutal ou une forte réduction.</p><p>Alcool Info Service explique que les manifestations de sevrage peuvent varier : anxiété, sommeil perturbé, sueurs ou tremblements font notamment partie des signes possibles. Certains tableaux sont graves et nécessitent une prise en charge urgente. Un planning de blog ne peut ni prédire ni sécuriser un sevrage individuel.</p><p>À ce stade, le repère utile peut être très concret : savoir qui contacter, comprendre l’accompagnement proposé et noter les questions à poser. Le bénéfice recherché n’est pas une performance de calendrier, mais une démarche adaptée à ta situation.</p>`],
['semaines','Au fil des semaines : sommeil, énergie et habitudes',`<p>Les ressources du NHS décrivent des bénéfices possibles de la réduction de consommation sur le sommeil, l’énergie, l’humeur et le budget. Leur apparition et leur intensité ne sont pas identiques pour tous. L’alcool peut perturber le sommeil même lorsqu’il semble faciliter l’endormissement.</p><p>Plutôt qu’une promesse à « J3 », « J7 » ou « J15 », choisis quelques observations répétables. Regarde comment se passent tes soirées, ton réveil et les moments associés auparavant à un verre. Tu peux noter « pas de changement perçu » : c’est une information valable.</p><div class="table-wrap"><table><caption>Des périodes pour organiser l’observation, sans échéance médicale</caption><thead><tr><th>Repère</th><th>Question utile</th><th>À ne pas en déduire</th></tr></thead><tbody><tr><td>Début de la démarche</td><td>Mon arrêt est-il préparé avec les appuis nécessaires ?</td><td>Que l’absence de symptôme garantit l’absence de risque.</td></tr><tr><td>Après plusieurs jours</td><td>Quelles habitudes et quelles envies ai-je repérées ?</td><td>Qu’un organe serait rétabli à une date précise.</td></tr><tr><td>Au fil des semaines</td><td>Qu’est-ce qui change dans mon repos, mon rythme ou mes dépenses ?</td><td>Que chaque variation a une cause unique.</td></tr><tr><td>Dans la durée</td><td>Quels appuis m’aident à conserver une démarche adaptée ?</td><td>Que tout risque antérieur a disparu.</td></tr></tbody></table></div>`],
['un-mois','À un mois : ce qu’une étude permet réellement de dire',`<p>Dans une étude publiée en 2018 dans BMJ Open, 94 personnes ayant choisi de s’abstenir pendant un mois ont été comparées à 47 personnes ayant continué leur consommation. Les chercheurs ont observé des améliorations de paramètres métaboliques, de la pression artérielle et du poids dans le groupe abstinent.</p><p>Il s’agissait d’une étude observationnelle, sans répartition aléatoire. Les personnes dépendantes ou avec une maladie hépatique connue étaient exclues. Les résultats sont intéressants, mais ne démontrent pas qu’une personne donnée obtiendra les mêmes changements, ni que le foie serait guéri au bout d’un mois.</p><p>La bonne lecture est donc : des changements mesurables ont été observés dans cette population à ce délai. Ce n’est ni un programme de soins, ni une promesse chiffrée de perte de poids ou de récupération pour tous.</p>`],
['long-terme','Dans la durée : garder le contexte de santé',`<p>La diminution de l’exposition à l’alcool peut réduire plusieurs risques pour la santé à plus long terme. Le NHS présente ces bénéfices avec les précautions nécessaires sur l’arrêt en situation de dépendance. Un article ne peut pas calculer le risque personnel à partir d’un compteur de jours.</p><p>La suite peut aussi faire émerger de nouveaux besoins : soutien social, suivi professionnel, nouvelles habitudes ou changement d’objectif. Une trajectoire n’a pas besoin d’être parfaitement linéaire pour être discutée et accompagnée.</p><p>Si tu souhaites partager des observations à une consultation, apporte les faits que tu connais, les symptômes éventuels et tes questions. La durée sans consommation est un élément de contexte parmi d’autres.</p>`],
['suivi','Construire ton propre tableau de bord',`<p>Choisis deux ou trois repères plutôt qu’une longue liste difficile à tenir. Un ${link('calendrier-sans-alcool-a-imprimer','calendrier de jours renseignés')}, une note sur ton sommeil et un budget approximatif peuvent déjà rendre la période plus lisible.</p><ul><li><strong>Faits :</strong> dates, consommations et dépenses connues.</li><li><strong>Ressentis :</strong> énergie, repos, envies et contexte.</li><li><strong>Appuis :</strong> personnes, activités et professionnels disponibles.</li></ul><p>Le ${link('compteur-jours-sans-alcool','compteur sans alcool')} peut situer une période ; le ${link('calcul-economies-arret-alcool','calculateur d’économies')} projette un budget. Aucun des deux ne mesure l’état de santé. Si tu te situes autour de dix à quinze jours, notre ${link('10-15-jours-sans-alcool-bienfaits','bilan de cette étape')} propose des questions plus ciblées.</p>`]
],
faq:[['Existe-t-il un tableau universel des bienfaits jour par jour ?','Non. On peut décrire des bénéfices possibles et des résultats d’études à certains délais, mais pas un calendrier garanti pour chaque personne.'],['La perte de poids est-elle automatique après l’arrêt ?','Non. Le poids dépend de nombreux éléments. Un changement observé dans une étude ne constitue pas un objectif ni une promesse individuelle.'],['Puis-je utiliser ces repères en réduisant sans arrêter ?','Tu peux observer tes habitudes et ressentis pendant une réduction. Les résultats d’une étude sur l’abstinence ne doivent cependant pas être appliqués tels quels à toutes les formes de réduction.']],
sources:['withdrawal','sleep','nhs','study','reduce']
},
{
slug:'ne-plus-boire-alcool-le-soir',title:'Ne plus boire d’alcool le soir : changer son rituel',category:'Traverser le quotidien',minutes:6,tool:eveningPlan,
description:'Comment ne plus boire d’alcool le soir ? Repère ton rituel, prépare une alternative et un appui. Un exercice gratuit, avec les précautions nécessaires.',
intro:'Le verre du soir peut être associé à la fin du travail, à la préparation du repas, à un moment de calme ou à une tension. Changer ce rituel commence par comprendre la place qu’il occupe. Voici un exercice d’organisation pour préparer une soirée différente, sans confondre une habitude avec un éventuel manque physique.',
sections:[
['comprendre','Repérer ce que représente le verre du soir',`<p>Avant de chercher par quoi remplacer l’alcool le soir, regarde le moment précis où l’envie apparaît. Est-ce juste après avoir fermé l’ordinateur ? En rentrant ? Pendant le repas ? Quand la maison devient silencieuse ? Le contexte peut donner une piste sur le besoin associé.</p><p>Alcool Info Service explique que les envies peuvent être déclenchées par des situations, des émotions et des habitudes liées à la consommation. Cela permet d’examiner une situation concrète plutôt que de s’attribuer une étiquette comme « je n’ai aucune volonté ».</p><p>Tu peux noter une seule phrase : « À cette heure-là, je cherche surtout à… ». Couper avec le travail, retrouver un lien et diminuer une tension ne sont pas le même besoin. L’alternative sera plus réaliste si elle tient compte de ce que tu attends de ce moment.</p>`],
['alternative','Préparer une alternative avant l’heure habituelle',`<p>Choisis une option accessible dans ta vraie soirée. Une boisson appréciée, un petit trajet à pied, de la musique, une douche ou une activité manuelle peuvent servir à créer une transition. Ce sont des pistes à adapter, sans résultat garanti sur une envie.</p><p>La préparation peut rester très simple : mettre la boisson au frais, préparer des chaussures ou décider à l’avance qui appeler. Une alternative trop compliquée risque surtout d’ajouter une tâche à une journée déjà lourde.</p><div class="callout"><p><strong>Exemple fictif :</strong> « Quand je rentre à 19 h, je prépare une eau pétillante, je mange si j’ai faim et je passe quelques minutes dehors avant de commencer le repas. Si la soirée devient difficile, je contacte la personne prévue. »</p></div><p>Si une boisson ressemblant à l’alcool renforce ton envie, choisis autre chose. Le bon rituel n’est pas celui qui a l’air le plus élaboré, mais celui qui convient à ton contexte et à ton accompagnement.</p>`],
['appui','Prévoir un appui plutôt que tout miser sur l’instant',`<p>Tu peux prévenir une personne de confiance que tu cherches à changer tes habitudes du soir. L’aide attendue peut être précise : un appel, une promenade ou simplement une réponse quand tu écris. Demande-lui ce qui est possible pour elle afin de garder un plan réaliste.</p><p>Un professionnel peut aussi aider à comprendre la consommation, les objectifs et les difficultés rencontrées. Ameli rappelle les aides disponibles pour réduire ou arrêter. Demander ce soutien ne nécessite pas d’avoir d’abord réussi seul plusieurs semaines.</p><p>Lorsque tu prépares un ${link('dry-january-2027-calendrier','défi de janvier sans alcool')}, pense particulièrement aux soirées habituelles et aux invitations. Une intention annoncée à l’avance peut faciliter l’organisation, sans t’obliger à expliquer ta situation personnelle à tout le monde.</p>`],
['envie','Quand une envie arrive malgré la préparation',`<p>Tu peux revenir à une action prévue : changer d’activité, t’éloigner d’une situation déclenchante si c’est possible, boire une boisson choisie ou joindre ton appui. Les ressources d’Alcool Info Service proposent plusieurs pistes pour ces moments.</p><p>Il n’est pas utile de promettre qu’une envie disparaîtra en un nombre précis de minutes. Si les tentatives restent difficiles ou si la consommation reprend, note ce qui s’est passé et cherche l’aide adaptée. Le plan du soir peut être ajusté ; il n’a pas à devenir un jugement sur toi.</p><p>Des tremblements, sueurs, malaises ou autres symptômes physiques ne doivent pas être interprétés comme un simple rituel à remplacer. Un avis médical permet d’évaluer ce qui se passe et la façon d’arrêter ou de réduire en sécurité.</p>`],
['relire','Relire la soirée le lendemain, sans procès',`<p>Trois lignes suffisent : ce que tu avais prévu, ce qui s’est réellement passé et ce que tu veux adapter. Tu peux noter une soirée difficile sans effacer les précédentes. Un ${link('calendrier-sans-alcool-a-imprimer','calendrier avec et sans consommation')} aide à conserver cette distinction.</p><p>Si tu utilises Sobrizen, le journal peut garder ces réflexions dans ton espace personnel. Le ${link('compteur-jours-sans-alcool','compteur de jours')} reste facultatif : l’observation des circonstances peut compter autant que le chiffre affiché.</p>`]
],
faq:[['Par quoi remplacer l’alcool le soir ?','Choisis une boisson appréciée et une activité correspondant au besoin de ce moment. Une alternative ne remplace pas un avis médical lorsqu’un manque physique ou une dépendance est possible.'],['Faut-il attendre que l’envie disparaisse pour demander de l’aide ?','Non. Tu peux solliciter une personne de confiance ou un professionnel dès la préparation de ta démarche.'],['Le plan saisi ici est-il conservé ?','Non. Il reste dans cette page et n’est pas envoyé à Sobrizen. Tu peux le recopier dans un endroit privé si tu veux le garder.']],
sources:['urges','dependence','reduce','withdrawal']
},
{
slug:'dry-january-2027-calendrier',title:'Dry January 2027 : calendrier et plan des 31 jours',category:'Le défi de janvier',minutes:6,
description:'Prépare ton Dry January 2027 : dates du 1er au 31 janvier, calendrier gratuit à imprimer, plan par semaine, budget et conseils pour les soirées.',
intro:'Le Dry January 2027, ou défi de janvier, se déroule du vendredi 1er au dimanche 31 janvier. Pour le préparer, tu peux utiliser un calendrier gratuit, anticiper tes soirées et choisir les observations qui t’intéressent. Sobrizen propose ici un guide indépendant ; le site officiel du mouvement en France est dryjanuary.fr.',
sections:[
['dates','Les dates du Dry January 2027',`<p>Le défi couvre les trente et un jours de janvier, du 1er au 31. En 2027, le mois commence un vendredi et se termine un dimanche. Il comprend cinq samedis et cinq dimanches : les week-ends méritent donc une place dans ta préparation si tes habitudes y sont différentes.</p><p>Le mouvement propose une pause avec l’alcool et une réflexion sur sa consommation. Il ne remplace pas un accompagnement médical. Une consommation importante ou quotidienne, des signes de manque ou un antécédent de sevrage difficile nécessitent de préparer l’arrêt avec un professionnel.</p><p>Le site <a href="https://dryjanuary.fr/">Dry January France</a> présente le mouvement, ses ressources et son application officielle Try Dry. Sobrizen n’est ni l’organisateur du défi ni son application officielle.</p>`],
['preparer','Avant le 1er janvier : préparer trois choses',`<ol><li><strong>Ton intention.</strong> Écris ce que tu souhaites observer ou changer, sans promesse de transformation physique.</li><li><strong>Les situations à anticiper.</strong> Repère une soirée habituelle, une invitation ou un moment de tension. Prépare une alternative réaliste et une personne à contacter.</li><li><strong>Ton support de suivi.</strong> Choisis un calendrier papier, un carnet ou une application. Quelques informations connues valent mieux qu’un suivi très détaillé abandonné rapidement.</li></ol><p>Notre ${link('calendrier-sans-alcool-a-imprimer','calendrier sans alcool à imprimer')} permet de choisir janvier 2027 et d’imprimer une page vierge. Le ${link('calcul-economies-arret-alcool','calculateur d’économies')} peut te donner un repère budgétaire, à partir de tes dépenses habituelles.</p>`],
['calendrier','Un plan pour les 31 jours de janvier',`<div class="table-wrap"><table><caption>Un plan d’organisation, sans protocole de soins</caption><thead><tr><th>Période</th><th>Point d’attention</th><th>Une action possible</th></tr></thead><tbody><tr><td>1er au 3 janvier</td><td>Poser le point de départ</td><td>Préparer le premier week-end et les appuis utiles.</td></tr><tr><td>4 au 10 janvier</td><td>Observer les routines</td><td>Noter un moment où l’envie revient et son contexte.</td></tr><tr><td>11 au 17 janvier</td><td>Faire un bilan intermédiaire</td><td>Identifier ce qui aide et ce qui demande du soutien.</td></tr><tr><td>18 au 24 janvier</td><td>Ajuster l’organisation</td><td>Adapter une alternative ou préparer une invitation.</td></tr><tr><td>25 au 31 janvier</td><td>Préparer la suite</td><td>Relire les observations et choisir ce que tu veux conserver.</td></tr></tbody></table></div><p>Ces périodes structurent le suivi, pas les réactions du corps. Elles ne signifient pas qu’une amélioration du sommeil, une perte de poids ou une récupération d’un organe devrait survenir telle semaine.</p>`],
['soirees','Comment préparer les soirées et les invitations ?',`<p>Tu peux décider à l’avance de ce que tu souhaites boire et de la réponse qui te convient si quelqu’un te propose de l’alcool. « Je fais une pause ce mois-ci » peut suffire. Tu n’as pas à partager d’informations personnelles pour justifier ce choix.</p><p>Prévois une boisson que tu apprécies, une personne avec qui échanger et, si nécessaire, la possibilité de partir. Pour les soirées à la maison, notre ${link('ne-plus-boire-alcool-le-soir','exercice sur le rituel du soir')} aide à formuler une alternative et un appui.</p><p>Si tu consommes pendant le mois, tu peux le noter sans transformer les autres journées en échec. Regarde le contexte et demande un soutien adapté si la situation devient difficile. Le calendrier distingue les journées ; il ne distribue pas de bons ou de mauvais points.</p>`],
['apres-janvier','Après janvier : que faire de ce que tu as appris ?',`<p>Le 31 janvier, tu peux relire tes observations : les occasions de consommation, les envies, les appuis, les dépenses et les ressentis. Une expérience d’un mois ne constitue pas un bilan médical, mais elle peut fournir des questions utiles pour la suite.</p><p>Tu peux discuter d’un objectif à plus long terme avec un professionnel, conserver un calendrier ou utiliser Sobrizen pour retrouver ton historique. Le plus utile est de garder une lecture honnête des faits, sans supposer qu’un mois efface tous les risques.</p><p>Pour distinguer les changements possibles des promesses trop précises, lis les ${link('bienfaits-arret-alcool-jour-apres-jour','repères sur les bienfaits de l’arrêt de l’alcool')}. Si tu veux seulement situer une période, le ${link('compteur-jours-sans-alcool','compteur gratuit')} reste disponible sans compte.</p>`]
],
faq:[['Quand commence et se termine le Dry January 2027 ?','Du vendredi 1er janvier au dimanche 31 janvier 2027 inclus. Le défi couvre trente et un jours.'],['Où trouver un calendrier gratuit pour janvier 2027 ?','Choisis janvier 2027 dans le calendrier de cet espace, puis imprime-le ou enregistre-le en PDF. Un PDF vierge de trente et une cases est également proposé.'],['Sobrizen est-il le site officiel du Dry January ?','Non. Ce guide est indépendant. Le site officiel du mouvement en France est dryjanuary.fr et son application officielle est Try Dry.'],['Puis-je commencer un arrêt brutal pour participer ?','Si ta consommation est importante ou quotidienne, ou si tu as des signes de manque, prépare la démarche avec un professionnel avant d’arrêter brutalement ou de réduire fortement.']],
sources:['dry','withdrawal','reduce','urges']
}
];
const additional=targetedContent({link,privacy});
Object.assign(sources,additional.sources);
articles.push(...additional.articles);
