for(const article of articles)article.related ||= relatedGuides[article.slug];

function head(title,description,path,type='article'){
  return `<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#faf9f5"><title>${escape(title)} | Sobrizen</title><meta name="description" content="${escape(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${origin+path}"><link rel="icon" type="image/png" href="/blog/logo-sobrizen.png"><link rel="stylesheet" href="/blog/blog.css"><meta property="og:locale" content="fr_FR"><meta property="og:type" content="${type}"><meta property="og:site_name" content="Sobrizen"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="${origin+path}"><meta property="og:image" content="${origin}/blog/logo-sobrizen.png"><meta property="og:image:alt" content="Logo Sobrizen"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${escape(title)}"><meta name="twitter:description" content="${escape(description)}">${type==='article'?`<meta property="article:published_time" content="${published}"><meta property="article:modified_time" content="${published}">`:''}</head>`;
}
const header=`<a class="skip" href="#contenu">Aller au contenu</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/blog" aria-label="SobriZen — Conseils et outils"><img src="/blog/logo-sobrizen.png" width="150" height="150" alt="SobriZen"></a><nav class="site-nav" aria-label="Navigation de l’espace public"><a href="/blog#articles">Les articles</a><a href="/blog#outils">Les outils</a><a class="button" href="/">Ouvrir Sobrizen <span aria-hidden="true">↗</span></a></nav></div></header>`;
const footer=`<footer class="site-footer"><div class="wrap footer-inner"><p>SobriZen · Des repères, à ton rythme.<br>Information générale et outils d’observation, sans diagnostic.</p><nav class="footer-links" aria-label="Liens utiles"><a href="/blog#redaction">Notre rédaction</a><a href="/legal#mentions">Mentions légales</a><a href="/legal#confidentialite">Confidentialité</a><a href="/">L’application</a></nav></div></footer>`;
function breadcrumb(article){return `<nav class="breadcrumbs" aria-label="Fil d’Ariane" itemscope itemtype="https://schema.org/BreadcrumbList"><span itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"><a itemprop="item" href="/"><span itemprop="name">Sobrizen</span></a><meta itemprop="position" content="1"></span><span aria-hidden="true">/</span><span itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"><a itemprop="item" href="/blog"><span itemprop="name">Conseils & outils</span></a><meta itemprop="position" content="2"></span><span aria-hidden="true">/</span><span itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"><a itemprop="item" href="${url(article.slug)}" aria-current="page"><span itemprop="name">${escape(article.category)}</span></a><meta itemprop="position" content="3"></span></nav>`;}
function renderArticle(article,index){
  const related=(article.related||[]).map(slug=>articles.find(a=>a.slug===slug)).filter(Boolean);
  for(const candidate of articles.filter(a=>a.slug!==article.slug)){
    if(related.length===3)break;
    if(!related.includes(candidate))related.push(candidate);
  }
  const toc=article.sections.map(([id,title])=>`<li><a href="#${id}">${escape(title)}</a></li>`).join('');
  const sourceHtml=article.sources.map(key=>{const [label,href]=sources[key];return `<li><a href="${href}">${label}</a></li>`;}).join('');
  return `<!doctype html><html lang="fr">${head(article.title,article.description,url(article.slug))}<body>${header}<main class="wrap" id="contenu">${breadcrumb(article)}<article itemscope itemtype="https://schema.org/BlogPosting" data-blog-article><link itemprop="mainEntityOfPage" href="${origin+url(article.slug)}"><meta itemprop="articleSection" content="${escape(article.category)}"><header class="article-header"><span class="eyebrow">${escape(article.category)} · ${article.minutes} min de lecture</span><h1 itemprop="headline">${escape(article.title)}</h1><p class="lede" itemprop="description">${article.intro}</p><div class="byline"><span itemprop="author" itemscope itemtype="https://schema.org/Organization"><a itemprop="url" href="${origin}/blog#redaction"><span itemprop="name">Rédaction Sobrizen</span></a></span><span aria-hidden="true">·</span><span>Publié le <time itemprop="datePublished dateModified" datetime="${published}">18 novembre 2026</time></span></div><span itemprop="publisher" itemscope itemtype="https://schema.org/Organization"><meta itemprop="name" content="Sobrizen"><link itemprop="url" href="${origin}/"></span></header><div class="reading-layout"><div class="article-body" itemprop="articleBody">${safety}${article.tool||''}${article.sections.map(([id,title,body])=>`<section id="${id}"><h2>${escape(title)}</h2>${body}</section>`).join('')}<section class="faq" id="questions"><h2>Questions fréquentes</h2>${article.faq.map(([q,a])=>`<details><summary>${escape(q)}</summary><p>${escape(a)}</p></details>`).join('')}</section><section class="sources" id="sources"><h2>Sources et méthode</h2><p>Sources consultées le 18 novembre 2026. Les exemples de budgets et de situations sont illustratifs. Ce contenu d’information ne constitue pas une consultation ni une validation médicale individuelle.</p><ol>${sourceHtml}</ol></section><section class="next-step"><span class="eyebrow" style="color:#c7e1d6">Un espace pour la suite</span><h2>Garde une trace de ton parcours.</h2><p>Jours renseignés, budget et journal : retrouve tes observations dans ton espace personnel, à ton rythme et sans jugement. Le compte gratuit permet de commencer ; des fonctions avancées sont proposées avec Premium.</p><a class="button" href="/">Découvrir Sobrizen <span aria-hidden="true">↗</span></a></section><section class="related" aria-label="Articles à poursuivre"><h2>Pour continuer</h2><div class="related-links">${related.map(a=>link(a.slug,escape(a.title)+' →')).join('')}</div></section></div><aside class="toc" aria-label="Sommaire de l’article"><strong>Dans cet article</strong><ol>${article.tool?'<li><a href="#'+(article.slug==='ne-plus-boire-alcool-le-soir'?'mon-plan':'outil')+'">Utiliser l’outil gratuit</a></li>':''}${toc}<li><a href="#questions">Questions fréquentes</a></li><li><a href="#sources">Sources</a></li></ol><p class="aside-note">Pas besoin d’un parcours parfait pour commencer à observer.</p><a href="/blog">← Tous les repères</a></aside></div></article></main>${footer}${article.tool?'<script type="module" src="/blog/tools.mjs"></script>':''}</body></html>\n`;
}
function renderIndex(){
  const toolCards=[['calendrier-sans-alcool-a-imprimer','▦','Le calendrier','Un mois, tes observations. À remplir puis à imprimer.'],['calcul-economies-arret-alcool','€','Les économies','Un budget concret, calculé à partir de tes habitudes.'],['compteur-jours-sans-alcool','↗','Le compteur','Une date de départ et un repère pour ta progression.'],['calcul-verres-standard-alcool','≃','Les quantités','Volume et degré : comprendre les verres standard.'],['journal-consommation-alcool-pdf','▤','Le journal PDF','Une semaine à remplir, avec un exemple pour commencer.']];
  return `<!doctype html><html lang="fr">${head('Alcool : conseils, calendrier et outils gratuits','Des repères pour réduire ou arrêter l’alcool : calendrier à imprimer, compteur de jours, calculateur d’économies et articles sourcés. Sans inscription pour les outils.','/blog','website')}<body>${header}<main class="wrap" id="contenu"><section class="hero"><div><span class="eyebrow">Le carnet SobriZen · Conseils & outils</span><h1>Des repères.<br>À ton rythme.</h1><p class="lede">Comprendre tes habitudes, préparer une soirée différente, voir le chemin parcouru. Des articles sourcés et des outils simples pour faire un pas à la fois.</p><div class="button-row"><a class="button" href="#outils">Trouver mon outil <span aria-hidden="true">↓</span></a><a class="button secondary" href="#articles">Lire les articles</a></div><p class="hero-note">Outils gratuits, sans compte. Une démarche sans jugement.</p></div><aside class="field-guide" aria-label="Trois façons de commencer"><div class="guide-top"><span>Un pas à la fois</span><span class="guide-sun" aria-hidden="true">✳</span></div><div class="guide-row"><span>01</span><a href="${url(articles[0].slug)}">Observer<small>Noter ce qui se passe, simplement.</small></a></div><div class="guide-row"><span>02</span><a href="${url(articles[4].slug)}">Comprendre<small>Lire les changements avec du recul.</small></a></div><div class="guide-row"><span>03</span><a href="${url(articles[5].slug)}">Préparer<small>Choisir le prochain petit pas.</small></a></div></aside></section><section class="tools-section" id="outils"><div class="section-head"><div><span class="eyebrow">À utiliser maintenant</span><h2>Des outils, un peu de clarté.</h2></div><p>Choisis ce qui t’aide aujourd’hui. Les saisies restent dans la page de l’outil, sans sauvegarde automatique.</p></div><div class="tool-cards">${toolCards.map(([slug,icon,title,description])=>`<a class="tool-card" href="${url(slug)}${slug==='journal-consommation-alcool-pdf'?'#modele':'#outil'}"><span class="tool-icon" aria-hidden="true">${icon}</span><h3>${title}</h3><p>${description}</p><span class="text-link">Utiliser l’outil gratuit →</span></a>`).join('')}</div></section><section class="article-section" id="articles"><div class="section-head"><div><span class="eyebrow">Comprendre, sans pression</span><h2>Les repères du carnet.</h2></div><p>Du rituel du soir aux étapes sans alcool : des réponses concrètes, avec leurs sources et leurs limites.</p></div><div class="article-list">${articles.map((a,i)=>`<a class="article-row" href="${url(a.slug)}"><span class="article-number">${String(i+1).padStart(2,'0')}</span><div><h3>${escape(a.title)}</h3><p>${escape(a.description)}</p></div><span class="article-tag">${escape(a.category)} ↗</span></a>`).join('')}</div></section><section class="editorial" id="redaction"><span class="eyebrow">La rédaction Sobrizen</span><h2>Des informations à remettre dans leur contexte.</h2><p>Ce carnet est publié par Sobrizen. Les articles sont préparés avec une aide à la rédaction par IA et s’appuient sur les sources indiquées dans chaque page. Ils ne sont pas présentés comme relus ou validés par un médecin. Ils n’établissent aucun diagnostic et ne remplacent pas un accompagnement adapté.</p><p>Les outils publics fonctionnent sans compte et ne transmettent pas leurs champs à l’application. Pour conserver un historique, tu peux imprimer tes observations ou choisir un espace personnel dans Sobrizen.</p>${safety}<p>Une remarque sur un article ? <a href="mailto:contact@sobrizen.com">contact@sobrizen.com</a> · <a href="https://www.alcool-info-service.fr/">Alcool Info Service : informations et accompagnement</a>.</p></section></main>${footer}</body></html>\n`;
}

mkdirSync(resolve(root,'blog'),{recursive:true});
writeFileSync(resolve(root,'blog.html'),renderIndex());
for(const [i,article] of articles.entries())writeFileSync(resolve(root,`blog/${article.slug}.html`),renderArticle(article,i));
const paths=['/blog',...articles.map(a=>url(a.slug))];
const sitemapPath=resolve(root,'sitemap.xml');
let sitemap=readFileSync(sitemapPath,'utf8').replace(/\s*<url><loc>https:\/\/www\.sobrizen\.com\/blog(?:<|\/)[\s\S]*?<\/url>/gu,'');
sitemap=sitemap.replace(/(<url><loc>https:\/\/www\.sobrizen\.com\/<\/loc><lastmod>)[^<]+/u,'$1'+published);
sitemap=sitemap.replace('</urlset>',paths.map(path=>`  <url><loc>${origin+path}</loc><lastmod>${published}</lastmod></url>`).join('\n')+'\n</urlset>');
writeFileSync(sitemapPath,sitemap);
console.log(`Generated blog index, ${articles.length} articles and sitemap entries.`);
